<?php
declare(strict_types=1);require_once __DIR__.'/product.php';
function migration_plan(): array{return['7.0.0'=>__DIR__.'/migrations/v7.sql','8.0.0'=>__DIR__.'/migrations/v8.sql','9.0.0'=>__DIR__.'/migrations/v9.sql','9.1.0'=>__DIR__.'/migrations/v9.1.sql','10.0.0'=>__DIR__.'/migrations/v10.sql','10.1.0'=>__DIR__.'/migrations/v10.1.sql','10.2.0'=>__DIR__.'/migrations/v10.2.sql','10.2.1'=>__DIR__.'/migrations/v10.2.1.sql'];}
function migration_has_tables(PDO $pdo): bool{return(int)$pdo->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()")->fetchColumn()>0;}
function migration_run(PDO $pdo,bool $bootstrap=false): array{$lock=(int)$pdo->query("SELECT GET_LOCK('crm_workspace_migrations',30)")->fetchColumn();if($lock!==1)throw new RuntimeException('Could not acquire the migration lock.');$applied=[];try{if($bootstrap&&!migration_has_tables($pdo))$pdo->exec((string)file_get_contents(__DIR__.'/schema.sql'));$pdo->exec('CREATE TABLE IF NOT EXISTS schema_versions (version VARCHAR(30) PRIMARY KEY, applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');$known=$pdo->query('SELECT version FROM schema_versions')->fetchAll(PDO::FETCH_COLUMN);foreach(migration_plan() as $version=>$file){if(in_array($version,$known,true))continue;if(!is_file($file))throw new RuntimeException('Missing migration '.$version);$sql=(string)file_get_contents($file);$sql=preg_replace('/^\s*SOURCE\s+.+?;\s*$/mi','',$sql)??$sql;$pdo->exec($sql);$st=$pdo->prepare('INSERT IGNORE INTO schema_versions(version) VALUES(?)');$st->execute([$version]);$applied[]=$version;}return$applied;}finally{$pdo->query("SELECT RELEASE_LOCK('crm_workspace_migrations')");}}
